<template>
 <view class="secondary-page">
  <PrototypePageHeader :title="tab==='invite'?(parent?'填写班级邀请码':'班级入学邀请码'):(parent?'申请记录':'入学申请审核')" icon="school"/>
  <view class="section">
   <text class="field-label">{{parent?'当前家庭':'管理组织'}}</text><picker :range="organizations" range-key="name" :value="orgIndex" :disabled="busy" @change="chooseOrg"><view class="picker-field"><text>{{organization?.name||(parent?'选择家庭':'选择学校或培训机构')}}</text><text>⌄</text></view></picker>
   <view class="segmented"><button :class="{active:tab==='requests'}" :disabled="busy" @tap="tab='requests';loadRequests()">{{parent?'申请记录':'入学审核'}}</button><button v-if="can(parent?'STUDENT_ENROLLMENT_REQUEST_CREATE':'STUDENT_ENROLLMENT_INVITE_CREATE')" :class="{active:tab==='invite'}" :disabled="busy" @tap="tab='invite'">{{parent?'填写邀请码':'班级邀请码'}}</button></view>
   <template v-if="tab==='requests'"><view class="segmented status-tabs"><button v-for="(label,i) in ['待审核','已通过','已拒绝']" :key="label" :class="{active:statusIndex===i}" :disabled="busy" @tap="switchStatus(i)">{{label}}<text v-if="statusCounts[i]" class="count-chip"> ({{statusCounts[i]}})</text></button></view></template>
   <template v-else-if="parent">
    <text class="field-label">成长小主人<text class="required">*</text></text><picker :range="children" range-key="studentName" :value="childIndex" :disabled="busy" @change="chooseChild"><view class="picker-field"><text>{{children[childIndex]?.studentName||'选择成长小主人'}}</text><text>⌄</text></view></picker>
    <text class="field-label">班级入学邀请码<text class="required">*</text></text><input v-model="code" placeholder="填写收到的班级邀请码" :disabled="busy" @input="invitation=null"/><button class="primary block-action" :disabled="busy||!code.trim()" @tap="resolve">核验邀请码</button>
   </template>
   <template v-else><text class="field-label">班级<text class="required">*</text></text><picker :range="scopedClasses" range-key="name" :value="classIndex" :disabled="busy" @change="chooseClass"><view class="picker-field"><text>{{scopedClasses[classIndex]?.name||'选择班级'}}</text><text>⌄</text></view></picker><button class="primary block-action" :disabled="busy||!scopedClasses[classIndex]" @tap="issue">生成入学邀请码</button></template>
  </view>
  <text v-if="error" class="error">{{error}}</text><view v-if="busy" class="empty">正在处理…</view>
  <template v-if="tab==='invite'">
   <view v-if="parent&&invitation" class="section"><view class="section-heading"><text class="section-title">入学信息</text><text class="badge">已核验</text></view><view class="detail-line"><text>学校 / 培训机构</text><text>{{invitation.institutionName}}</text></view><view class="detail-line"><text>班级</text><text>{{invitation.className}}</text></view><text class="meta">有效期至 {{enrollmentDate(invitation.expiresAt)}}</text><button class="primary block-action" :disabled="busy||!studentUserId||!organization" @tap="apply">提交入学申请</button></view>
   <view v-else-if="!parent&&invitation?.inviteCode" class="section invitation-card">
    <view class="invitation-class"><view class="person"><PrototypeIcon name="school" :size="38"/></view><view class="person-copy"><text class="name">{{invitation.className}}</text><text class="meta">{{invitation.institutionName}}</text></view></view>
    <view class="qr-content"><InvitationQrCode :value="invitation.inviteCode"/><text class="small">班级入学邀请码</text><text selectable class="invite-code">{{invitation.inviteCode}}</text><text class="meta">有效期至 {{enrollmentDate(invitation.expiresAt)}}</text></view>
    <view class="invitation-actions"><button class="secondary action-cell" :disabled="busy" @tap="copyCode">复制邀请码</button><button class="secondary action-cell" :disabled="busy||!invitation.id" @tap="startExpiryEdit">设置有效期</button><button class="secondary action-cell" :disabled="busy" @tap="openPoster">生成海报</button></view>
    <view v-if="expiryEditing" class="reject-form"><text class="field-label">有效期（天）<text class="required">*</text></text><input v-model="expiryDays" class="expiry-input" type="number" placeholder="请输入有效天数（1-30）" maxlength="3" :disabled="busy"/><view class="action-grid"><button class="secondary" :disabled="busy" @tap="expiryEditing=false">取消</button><button class="primary" :disabled="busy" @tap="saveExpiry">确认保存</button></view></view>
    <text class="invitation-warning">该邀请码仅限本班级使用，请勿分享给其他学校或机构</text>
   </view>
  </template>
  <template v-else>
   <view v-for="item in requests" :key="item.id" class="section request-card">
    <view class="row request-person"><view class="person"><PrototypeIcon name="user" :size="36"/></view><view class="person-copy"><text class="name">{{item.studentName}}</text><text class="meta">{{item.className}}</text></view><text class="badge" :class="item.status">{{statusName(item.status)}}</text></view>
    <view class="detail-line"><text>申请组织</text><text>{{item.institutionName}}</text></view><view class="detail-line"><text>申请班级</text><text>{{item.className}}</text></view><view class="detail-line"><text>申请时间</text><text>{{enrollmentDate(item.createdAt)}}</text></view><view v-if="item.applicantName" class="detail-line"><text>申请人</text><text>{{item.applicantName}}{{maskedMobile(item.applicantMobile)?' '+maskedMobile(item.applicantMobile):''}}</text></view><view v-if="item.reviewedAt" class="detail-line"><text>审核时间</text><text>{{enrollmentDate(item.reviewedAt)}}</text></view><text v-if="item.reviewReason" class="review-reason">审核意见：{{item.reviewReason}}</text>
    <template v-if="!parent&&item.status==='PENDING'&&can('STUDENT_ENROLLMENT_REVIEW')">
     <view v-if="rejecting!==item.id" class="action-grid"><button class="secondary" :disabled="busy" @tap="rejecting=item.id;reason=''">拒绝申请</button><button class="primary" :disabled="busy" @tap="review(item,true)">通过申请</button></view>
     <view v-else class="reject-form"><text class="field-label">拒绝原因<text class="required">*</text></text><textarea v-model="reason" placeholder="填写原因，便于申请人修改" maxlength="200" :disabled="busy"/><text class="counter">{{reason.length}} / 200</text><view class="action-grid"><button class="secondary" :disabled="busy" @tap="rejecting=''">取消</button><button class="danger" :disabled="busy||!reason.trim()" @tap="review(item,false)">确认拒绝</button></view></view>
    </template>
   </view>
   <view v-if="!busy&&!requests.length&&!error" class="section empty"><PrototypeIcon name="book" tone="muted" :size="64"/><text>暂无入学申请</text></view>
  </template>
 </view>
</template>
<script setup lang="ts">
import PrototypePageHeader from "@/components/PrototypePageHeader.vue";
import InvitationQrCode from '@/components/InvitationQrCode.vue';
import {computed,ref} from 'vue';import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app';import PrototypeIcon from '@/components/PrototypeIcon.vue';import {request} from '@/api/http';import {getOrganizationSession} from '@/session/organization-session';import {getParentSession} from '@/session/parent-session';import {onboardingApi,type MyOrganization} from '@/api/organization-onboarding';import {listManagedClasses,type OrganizationClass} from '@/api/organization-classes';import {parentChildrenApi,type Child} from '@/api/parent-children';import {institutionEnrollmentApi,enrollmentDate,maskedMobile,type InstitutionInvitation,type EnrollmentRequest} from '@/api/institution-enrollment';
const parent=ref(false),organizations=ref<MyOrganization[]>([]),orgIndex=ref(0),classes=ref<OrganizationClass[]>([]),classIndex=ref(0),children=ref<Child[]>([]),childIndex=ref(0),studentUserId=ref(''),permissions=ref<string[]>([]),tab=ref('requests'),busy=ref(false),error=ref(''),code=ref(''),invitation=ref<InstitutionInvitation|null>(null),requests=ref<EnrollmentRequest[]>([]),statusIndex=ref(0),statusCounts=ref<number[]>([0,0,0]),rejecting=ref(''),reason=ref('');const statuses=['PENDING','APPROVED','REJECTED'];const organization=computed(()=>organizations.value[orgIndex.value]);const scopedClasses=computed(()=>classes.value.filter(c=>c.id===organization.value?.id||c.schoolOrganizationId===organization.value?.id||c.parentId===organization.value?.id));const can=(p:string)=>permissions.value.includes(p);const session=()=>parent.value?getParentSession():getOrganizationSession();let epoch=0,requestedClass='';const valid=(n:number,t:string)=>n===epoch&&session()?.accessToken===t;
onLoad(q=>{parent.value=q?.identity==='parent';requestedClass=q?.classId||'';if(q?.code){code.value=q.code;tab.value='invite';}});function hide(){epoch++;busy.value=false;invitation.value=null;studentUserId.value='';requests.value=[];permissions.value=[];organizations.value=[];classes.value=[];children.value=[];rejecting.value='';error.value='';}onHide(hide);onUnload(hide);
async function run<T>(task:(token:string)=>Promise<T>,done:(result:T)=>void){const s=session();if(!s||busy.value)return false;const n=++epoch;busy.value=true;error.value='';try{const result=await task(s.accessToken);if(valid(n,s.accessToken)){done(result);return true;}}catch(e){if(valid(n,s.accessToken))error.value=e instanceof Error?e.message:'请求失败';}finally{if(valid(n,s.accessToken))busy.value=false;}return false;}
onShow(async()=>{permissions.value=[];organizations.value=[];classes.value=[];children.value=[];const s=session();if(!s){uni.reLaunch({url:'/pages/unified-login/unified-login'});return;}const loaded=await run(async token=>{const initEpoch=epoch;const [me,orgs]=await Promise.all([request<{permissionCodes:string[]}>('/auth/me',{header:{Authorization:`Bearer ${token}`}}),onboardingApi.organizations(token)]);if(!valid(initEpoch,token))throw new Error('页面会话已改变');const childPage={items:[] as Child[]};if(parent.value&&me.permissionCodes.includes('STUDENT_READ')){const n=initEpoch;let page=1,total=1;while(childPage.items.length<total){const rows=await parentChildrenApi.list(token,page++);if(!valid(n,token))throw new Error('页面会话已改变');childPage.items.push(...rows.items);total=rows.total;if(!rows.items.length)break;}}if(!valid(initEpoch,token))throw new Error('页面会话已改变');const cls=!parent.value&&me.permissionCodes.includes('CLASS_READ')?await listManagedClasses(token):[];return {me,orgs,childPage,cls};},result=>{permissions.value=result.me.permissionCodes;organizations.value=result.orgs.filter(o=>parent.value?o.typeCode==='FAMILY'&&o.canEnterFamily:o.canEnterInstitution&&['SCHOOL','TRAINING_INSTITUTION','CLASS'].includes(o.typeCode));classes.value=result.cls;children.value=result.childPage?.items||[];if(!organizations.value.length)error.value=parent.value?'没有可进入的家庭组织':'没有可直接管理的学校、培训机构或班级组织';orgIndex.value=0;const stored=uni.getStorageSync('lingdong.selected-organization') as {accessToken?:string;organizationId?:string};if(stored?.accessToken===s.accessToken)orgIndex.value=Math.max(0,organizations.value.findIndex(o=>o.id===stored.organizationId));classIndex.value=Math.max(0,scopedClasses.value.findIndex(c=>c.id===requestedClass));});if(!loaded||session()?.accessToken!==s.accessToken||error.value)return;if(parent.value&&children.value.length){const childLoaded=await loadChild();if(!childLoaded)return;}await loadRequests();});
async function loadChild(){studentUserId.value='';const child=children.value[childIndex.value];if(!child)return false;return run(token=>request<Child&{studentUserId?:string}>(`/students/${encodeURIComponent(child.id)}`,{header:{Authorization:`Bearer ${token}`}}),detail=>{studentUserId.value=detail.studentUserId||'';if(!studentUserId.value)error.value='学生详情尚未提供入学申请所需的学生用户标识，请联系学校。';});}
async function loadRequests(){requests.value=[];if(!organization.value||!can(parent.value?'STUDENT_ENROLLMENT_REQUEST_CREATE':'STUDENT_ENROLLMENT_REVIEW')){if(can(parent.value?'STUDENT_ENROLLMENT_REQUEST_CREATE':'STUDENT_ENROLLMENT_INVITE_CREATE'))tab.value='invite';return;}const scopeKey=parent.value?'familyOrganizationId':organization.value!.typeCode==='CLASS'?'classOrganizationId':'institutionOrganizationId';const scopeId=organization.value!.id;await run(async token=>{const base={[scopeKey]:scopeId};const [current,pending,approved,rejected]=await Promise.all([institutionEnrollmentApi.list(token,{...base,status:statuses[statusIndex.value]}),institutionEnrollmentApi.list(token,{...base,status:'PENDING'}),institutionEnrollmentApi.list(token,{...base,status:'APPROVED'}),institutionEnrollmentApi.list(token,{...base,status:'REJECTED'})]);statusCounts.value=[pending.length,approved.length,rejected.length];return current;},rows=>{requests.value=Array.isArray(rows)?rows:[];});}function chooseOrg(e:{detail:{value:string}}){if(busy.value)return;orgIndex.value=Number(e.detail.value);classIndex.value=0;invitation.value=null;loadRequests();}function chooseClass(e:{detail:{value:string}}){if(busy.value)return;classIndex.value=Number(e.detail.value);invitation.value=null;}function chooseChild(e:{detail:{value:string}}){if(busy.value)return;childIndex.value=Number(e.detail.value);loadChild();}function switchStatus(index:number){if(busy.value)return;statusIndex.value=index;loadRequests();}
async function authorize(token:string,permission:string){const n=epoch;const me=await request<{permissionCodes:string[]}>('/auth/me',{header:{Authorization:`Bearer ${token}`}});if(!valid(n,token))throw new Error('页面会话已改变');if(!me.permissionCodes.includes(permission))throw new Error('当前操作权限已失效');}async function issue(){const c=scopedClasses.value[classIndex.value];if(!c||!can('STUDENT_ENROLLMENT_INVITE_CREATE'))return;await run(async token=>{await authorize(token,'STUDENT_ENROLLMENT_INVITE_CREATE');return institutionEnrollmentApi.issue(token,c.id);},value=>{invitation.value=value;});}async function resolve(){invitation.value=null;await run(token=>institutionEnrollmentApi.resolve(token,code.value.trim()),value=>{invitation.value=value;});}async function apply(){if(!studentUserId.value||!organization.value||!invitation.value||!can('STUDENT_ENROLLMENT_REQUEST_CREATE'))return;const target={studentUserId:studentUserId.value,familyOrganizationId:organization.value.id,code:code.value.trim()};const applied=await run(async token=>{await authorize(token,'STUDENT_ENROLLMENT_REQUEST_CREATE');return institutionEnrollmentApi.apply(token,target.studentUserId,target.familyOrganizationId,target.code);},()=>{uni.showToast({title:'申请已提交',icon:'success'});tab.value='requests';invitation.value=null;});if(applied)await loadRequests();}async function review(item:EnrollmentRequest,approved:boolean){if(busy.value||!can('STUDENT_ENROLLMENT_REVIEW')||(!approved&&!reason.value.trim()))return;const reviewReason=reason.value.trim();busy.value=true;const before=epoch,token=session()?.accessToken;const confirm=await uni.showModal({title:approved?'确认通过入学申请':'确认拒绝入学申请',content:`${item.studentName} · ${item.className}`});if(!confirm.confirm||before!==epoch||token!==session()?.accessToken){if(before===epoch)busy.value=false;return;}busy.value=false;const reviewed=await run(async t=>{await authorize(t,'STUDENT_ENROLLMENT_REVIEW');return approved?institutionEnrollmentApi.approve(t,item.id):institutionEnrollmentApi.reject(t,item.id,reviewReason);},()=>{rejecting.value='';uni.showToast({title:'审核已完成',icon:'success'});});if(reviewed)await loadRequests();}function copyCode(){if(invitation.value?.inviteCode)uni.setClipboardData({data:invitation.value.inviteCode});}
function openPoster(){uni.showToast({title:'海报生成暂未开放',icon:'none'});}
const expiryEditing=ref(false),expiryDays=ref('');
function startExpiryEdit(){const current=invitation.value;if(!current?.id||busy.value)return;expiryDays.value='';expiryEditing.value=true;}
async function saveExpiry(){const current=invitation.value;if(!current?.id||busy.value)return;const days=Number(expiryDays.value.trim());if(!Number.isInteger(days)||days<1||days>30){error.value='有效天数必须为1至30';return;}const updated=await run(token=>institutionEnrollmentApi.updateExpiry(token,current.id!,days),value=>{expiryEditing.value=false;if(invitation.value&&invitation.value.id===current.id)invitation.value={...invitation.value,expiresAt:value.expiresAt};uni.showToast({title:'有效期已更新',icon:'success'});});if(!updated)uni.showToast({title:error.value||'有效期更新失败',icon:'none'});}function statusName(s:string){return ({PENDING:'待审核',APPROVED:'已通过',REJECTED:'已拒绝'} as Record<string,string>)[s]||s;}
</script>
<style scoped>
.secondary-page,.prototype-workspace{padding:24rpx 28rpx 60rpx;min-height:calc(100vh - var(--window-top,0px));box-sizing:border-box;background:#f6f9f5;color:#172e25}.has-footer,.has-tabbar{padding-bottom:160rpx}.prototype-section-header{display:flex;justify-content:center;align-items:center;gap:12rpx;margin:-24rpx -28rpx 24rpx;padding:28rpx;background:linear-gradient(120deg,#206b52,#0c4f3e);color:white;font-size:32rpx;font-weight:650}.section,.form-band,.band,.heading-band{background:#fff;border:1rpx solid #e4ece3;border-radius:24rpx;padding:26rpx;margin-bottom:22rpx}.segmented,.mode-control,.tabs,.action-grid,.form-actions,.paging,.search-row,.two-columns{display:flex;align-items:center;gap:14rpx;margin:18rpx 0}.segmented button,.mode-control button,.tab,.action-grid button{flex:1}.active{background:#e2f2e6;color:#0a774d}.field-label{display:block;font-size:26rpx;margin:20rpx 0 12rpx}.picker-field,.picker-value,.field,input,textarea{background:#f7faf6;border:1rpx solid #dfe8dc;border-radius:16rpx;padding:18rpx;font-size:26rpx;box-sizing:border-box}.picker-field{display:flex;justify-content:space-between}.search-row input{flex:1;min-width:0}textarea{width:100%;min-height:180rpx}.row,.request-person,.invitation-class{display:flex;align-items:center;gap:18rpx;padding:24rpx 0;border-bottom:1rpx solid #e8eee6}.person{width:80rpx;height:80rpx;border-radius:50%;background:#e2eee3;display:flex;align-items:center;justify-content:center;flex-shrink:0}.person-copy{flex:1;min-width:0}.row-top,.section-heading,.detail-line,.list-head{display:flex;justify-content:space-between;align-items:center;gap:12rpx}.name,.section-title,.title,.form-title{font-size:30rpx;font-weight:650}.meta,.small,.counter{display:block;font-size:23rpx;color:#778179;line-height:1.7}.badge,.status{border-radius:12rpx;background:#e2f4e7;color:#13734d;padding:4rpx 12rpx;font-size:23rpx}.PENDING,.submitted{background:#fff0cb;color:#b37a20}.detail-line{font-size:25rpx;padding:15rpx 0}.error,.danger{color:#ac4